#!/usr/bin/env python3
"""Render the general spin-2 upper bound and its rigorously limited scope."""
from pathlib import Path
import json,re,html,hashlib
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def tex(s,display=False):
 return '<div class="math" data-display="true" data-tex="'+html.escape(s,quote=True)+'"></div>' if display else '<span class="math" data-tex="'+html.escape(s,quote=True)+'"></span>'
def main():
 data=json.loads((ROOT/'data/catalogue.json').read_text());baseline=json.loads((HERE/'baseline-entries.json').read_text());old={e['id']:e for e in baseline}
 changes=[]
 for e in data['entries']:
  b=old[e['id']]
  if (e['lower'],e['upper'])!=(b['lower'],b['upper']):changes.append({'n':e['n'],'t':e['t'],'previousLower':b['lower'],'previousUpper':b['upper'],'lower':e['lower'],'upper':e['upper'],'status':e['status']})
 assert changes==[{'n':20,'t':2,'previousLower':2,'previousUpper':4,'lower':4,'upper':4,'status':'proven'},{'n':42,'t':2,'previousLower':4,'previousUpper':10,'lower':4,'upper':9,'status':'range'}]
 report={'theorem':'5k <= N+5 for N>=4 and AC order t>=2','combinedUpper':'min(floor((N-2)/4),floor((N+5)/5)) for N>=8','generalAttainmentProved':False,'improvements':changes,'catalogueSha256':hashlib.sha256((ROOT/'data/catalogue.json').read_bytes()).hexdigest()};(HERE/'improvements.json').write_text(json.dumps(report,indent=2)+'\n')
 css=re.search(r'<style>(.*?)</style>',(ROOT/'research/ancilla-inertia/index.html').read_text(),re.S).group(1)
 eigens=[('j-2','-2(j+1)','N-3'),('j-1','-2j(j+1)','N-1'),('j','-j(2j+5)','N+1'),('j+1','-5j-2','N+3'),('j+2','4j(j+1)','N+5')]
 rows=''.join('<tr>'+''.join('<td>'+tex(x)+'</td>' for x in row)+'</tr>' for row in eigens)
 body='''<p class="eyebrow">Anticoherent subspaces · General second-order bound</p><a class="back-link" href="../../index.html#n=42&amp;t=2">← Return to the catalogue</a>
<h1>A stronger upper bound at second order</h1><p class="lead">Auxiliary spin two yields a bound with asymptotic coefficient one fifth. The earlier one-quarter bound cannot be the exact maximum for every size.</p>
<div class="result"><strong>General upper bound</strong>'''+tex(r'\boxed{5k\le N+5\qquad(N\ge4,\ t\ge2)}',True)+'''<p>Combining this with the auxiliary spin-3/2 theorem gives</p>'''+tex(r'K(N,2)\le\min\!\left\{\left\lfloor\frac{N-2}{4}\right\rfloor,\left\lfloor\frac{N+5}{5}\right\rfloor\right\}\qquad(N\ge8).',True)+'''</div>
<h2>The whole-subspace conditions</h2><p>For '''+tex(r'j=N/2')+''' and a second-order AC projector '''+tex('P')+''', polarization of the first two moments gives</p>'''+tex(r'PJ_aP=0,\qquad PJ_aJ_bP=\frac{j(j+1)}3\delta_{ab}P.',True)+'''<p>The antisymmetric second moment is a first-order spin component, so the equation also holds for ordered products.</p>
<h2>A quadratic auxiliary operator</h2><p>Take spin-2 generators '''+tex('S_a')+''' on '''+tex(r'\mathbb C^5')+''' and define</p>'''+tex(r'X=\mathbf J\cdot\mathbf S,\qquad W=X^2+(j+3)X-2j(j+1)I,\qquad\Pi=P\otimes I_5.',True)+'''<p>Since '''+tex(r'\sum_aS_a^2=6I_5')+''', the full compression identities imply</p>'''+tex(r'\Pi X\Pi=0,\qquad\Pi X^2\Pi=2j(j+1)\Pi,\qquad\boxed{\Pi W\Pi=0}.',True)+'''
<h2>Five eigenvalues with fixed signs</h2><p>When '''+tex(r'j\ge2')+''', total spin ranges from '''+tex(r'j-2')+''' to '''+tex(r'j+2')+'''. On a total-spin sector '''+tex('L')+''',</p>'''+tex(r'X=\frac{L(L+1)-j(j+1)-6}{2}.',True)+'''<div class="table-wrap"><table class="classification"><thead><tr><th>Total spin</th><th>Eigenvalue of '''+tex('W')+'''</th><th>Multiplicity</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><p>The first four eigenvalues are strictly negative and the last is strictly positive. Thus '''+tex('W')+''' has '''+tex('N+5')+''' positive directions, '''+tex('4N')+''' negative directions and no zero directions.</p>
<h2>The dimension argument</h2><p>Projection of '''+tex(r'\mathcal C\otimes\mathbb C^5')+''' into the positive eigenspace is injective. A nonzero vector in the projection kernel would lie entirely in the negative eigenspace, contradicting zero compression. Therefore</p>'''+tex(r'5k=\dim(\mathcal C\otimes\mathbb C^5)\le N+5.',True)+'''<p>The argument applies to arbitrary complex AC subspaces. No symmetry or sparse-support assumption is used.</p>
<h2>What is settled, and what is still open?</h2><p>The existing analytical witnesses attain the combined bound throughout '''+tex(r'8\le N\le17')+''':</p>'''+tex(r'K(N,2)=\begin{cases}1,&N=8,9,\\2,&10\le N\le13,\\3,&14\le N\le17.\end{cases}',True)+'''<p>Numerical dimension-four examples are available at '''+tex(r'N=18,19')+'''. They remain numerical evidence, separate from certified existence. An exact algebraic certificate now proves <a href="../n20-t2/index.html">K(20,2)=4</a>. A general analytical family attaining the combined upper bound has not been established.</p><div class="certificate"><strong>The previous upper bound is not always attainable</strong>'''+tex(r'\left\lfloor\frac{34-2}{4}\right\rfloor=8,\qquad K(34,2)\le\left\lfloor\frac{34+5}{5}\right\rfloor=7.',True)+'''<p>This is the first integer improvement over the older bound. It rules out that older formula as a universal equality; it does not prove '''+tex('K(34,2)=7')+'''.</p></div><p>The general upper bound is therefore proved. Its universal tightness remains an existence question.</p>
<h2>Catalogue improvement</h2><p>The new upper bound improves the displayed interval</p>'''+tex(r'(N,t)=(42,2):\qquad4\le K(42,2)\le10\quad\longrightarrow\quad4\le K(42,2)\le9.',True)+'''<p><a href="../../index.html#n=42&amp;t=2">Inspect the 42-qubit bound and exact dimension-four Molien witness ↗</a>. Its status remains a rigorous interval. Separately, the <a href="../n20-t2/index.html">twenty-qubit algebraic construction</a> raises the lower bound from two to four and proves the maximum is four. All earlier representative states are retained.</p>
<h2>Proof and reproducibility</h2><p><a href="proof.tex">Complete LaTeX proof ↓</a> · <a href="verify.py">Exact verifier ↓</a> · <a href="verification.json">Verification report ↓</a> · <a href="verify_independently.py">Independent verifier ↓</a> · <a href="independent-verification.json">Independent verification ↓</a> · <a href="improvements.json">Changed bounds ↓</a></p><p>The displayed polynomial identities and their signs prove the theorem for every size in its domain. Finite checks validate conventions and implementation. No claim of literature priority is made.</p><footer><a href="../ancilla-inertia/index.html">The complementary auxiliary spin-3/2 bound ↗</a> · <a href="../t1-optimality/index.html">The exact first-order maximum ↗</a></footer>'''
 head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A stronger general second-order AC-subspace bound</title><link rel="stylesheet" href="../../vendor/katex/katex.min.css"><script defer src="../../vendor/katex/katex.min.js"></script><style>'+css+'</style><script>document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-tex]").forEach(el=>{if(window.katex)el.innerHTML=katex.renderToString(el.dataset.tex,{displayMode:el.dataset.display==="true",throwOnError:false,strict:"ignore",trust:false});}));</script></head><body><main>'
 (HERE/'index.html').write_text(head+body+'</main></body></html>\n')
 print(json.dumps(report,indent=2))
if __name__=='__main__':main()
